function e(e,t,n){let r=t.filter(t=>t.teamId===e.id),i=n.filter(t=>t.homeTeamId===e.id||t.awayTeamId===e.id),a=0,o=0,s=0,c=0,l=0,u=0;for(let t of i){let n=t.homeTeamId===e.id,r=n?t.goalsHomeTeam:t.goalsAwayTeam,i=n?t.goalsAwayTeam:t.goalsHomeTeam;c+=r,l+=i,u+=t.attendance,r>i?a+=1:r<i?s+=1:o+=1}return{team:e,playerCount:r.length,matchesPlayed:i.length,wins:a,draws:o,losses:s,goalsFor:c,goalsAgainst:l,goalDifference:c-l,totalAttendance:u,averageAttendance:i.length===0?0:Math.round(u/i.length),playerGoals:r.reduce((e,t)=>e+t.goals,0),playerAssists:r.reduce((e,t)=>e+t.assists,0)}}export{e as t};